20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName",
24	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality",
30	        expression = "java(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode()))")
31	    @Mapping(target = "contactPreference",
32	        expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "checkDigit",
35	        expression = "java(org.springframework.samples.petclinic.util.CheckDigits.luhn(owner.getCustomerCode()))")
36	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
37	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
38	    @Mapping(target = "telephoneDisplay",
39	        expression = "java(org.springframework.samples.petclinic.util.TelephoneFormatter.toDisplay(owner.getTelephone()))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /** Age band derived from birthDate against registrationDate: MINOR (under 18), ADULT (18-64) or SENIOR (65+); null when birthDate is absent. */
43	    default String ageBand(Owner owner) {
44	        java.time.LocalDate birthDate = owner.getBirthDate();
45	        if (birthDate == null || owner.getRegistrationDate() == null) {
46	            return null;
47	        }
48	        int age = java.time.Period.between(birthDate, owner.getRegistrationDate()).getYears();
49	        if (age < 18) {
50	            return "MINOR";
51	        }
52	        return age < 65 ? "ADULT" : "SENIOR";
53	    }
54	
